head.b:skin:
/* -----------------------------------------------
   Blogger Template Style
   Name    : SaeKabar — Portal Berita
   Version : 3.1.2
----------------------------------------------- */
/*
<Group description="Warna Tema" selector="body">
  <Variable name="red.color" description="Merah utama" type="color" default="#e82724" value="#e82724"/>
  <Variable name="accent.color" description="Merah aksen (label, garis judul)" type="color" default="#ed1c24" value="#ed1c24"/>
  <Variable name="purple.color" description="Ungu (ujung gradien)" type="color" default="#41227a" value="#41227a"/>
  <Variable name="ink.color" description="Warna teks utama (judul, isi artikel)" type="color" default="#1e1e1e" value="#1e1e1e"/>
  <Variable name="grey.color" description="Warna teks sekunder (tanggal, penulis, meta)" type="color" default="#666666" value="#666666"/>
  <Variable name="line.color" description="Warna garis/border" type="color" default="#dddddd" value="#dddddd"/>
  <Variable name="soft.color" description="Warna latar lembut (kotak, toolbar, kartu)" type="color" default="#f6f6f6" value="#f6f6f6"/>
  <Variable name="bg.color" description="Warna latar halaman" type="color" default="#ffffff" value="#ffffff"/>
  <Variable name="link.color" description="Warna tautan di isi artikel" type="color" default="#cc0000" value="#cc0000"/>
</Group>
<Group description="Ukuran Teks" selector="body">
  <Variable name="title.size" description="Ukuran judul artikel" type="length" min="20px" max="44px" default="30px" value="30px"/>
  <Variable name="body.size" description="Ukuran teks isi artikel" type="length" min="13px" max="20px" default="16px" value="16px"/>
</Group>
<Group description="Tata Letak" selector="body">
  <Variable name="radius.size" description="Kelengkungan sudut gambar dan kartu" type="length" min="0px" max="24px" default="8px" value="8px"/>
</Group>
*/
:root{--red:$(red.color);--red2:$(accent.color);--purple:$(purple.color);--ink:$(ink.color);--grey:$(grey.color);--line:$(line.color);--soft:$(soft.color);--bg:$(bg.color);--link:$(link.color);--title-size:$(title.size);--body-size:$(body.size);--radius:$(radius.size);--font:'Montserrat',sans-serif;--grad:linear-gradient(90deg,var(--red),var(--purple));--red-t:#c5211f;--red2-t:#c9181f}
@supports (color:color-mix(in srgb,red,blue)){:root{--red-t:color-mix(in srgb,var(--red) 85%,#000);--red2-t:color-mix(in srgb,var(--red2) 85%,#000)}}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;font-family:var(--font);color:var(--ink);background:var(--bg);font-size:16px;line-height:1.5;-webkit-font-smoothing:antialiased}
a{color:inherit;text-decoration:none}
a:hover{color:var(--red2-t)}
img{max-width:100%;height:auto;display:block}
h1,h2,h3,h4,h5,p{margin:0}
ul,ol{margin:0;padding:0;list-style:none}
button{font-family:inherit;cursor:pointer}
svg{width:20px;height:20px;fill:currentColor;flex:0 0 auto}
.sz-wrap{max-width:1105px;margin:0 auto;padding:0 15px}
.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
.section{margin:0}
.widget{margin:0}
#attribution{display:none}
.mt-30{margin-top:30px}

/* ===== HEADER ===== */
.sz-header{position:sticky;top:0;z-index:60;background:#fff;padding:15px 0;transition:box-shadow .2s}
.sz-scrolled .sz-header{box-shadow:0 6px 16px rgba(0,0,0,.15)}
.sz-header-in{display:flex;align-items:center;height:35px}
.sz-logo{flex:0 1 237px;min-width:0;width:237px}
.sz-logo .widget{margin:0}
.sz-logo-h{margin:0;font-size:inherit;line-height:1}
.sz-logo-link{display:inline-flex;align-items:center;min-width:0;max-width:100%}
.sz-logo img{max-height:36px;max-width:100%;width:auto;height:auto;object-fit:contain}
.sz-logo-alt{display:none}
.sz-logo-text{display:inline-block;min-width:0;max-width:100%;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;vertical-align:middle;font-size:30px;font-weight:800;letter-spacing:-.8px;line-height:1;background:var(--grad);-webkit-background-clip:text;background-clip:text;color:transparent;text-transform:lowercase}
.sz-search{flex:1;min-width:0;display:flex;justify-content:center;padding:0 10px}
.sz-search form{width:550px;max-width:100%;position:relative}
.sz-search input{width:100%;height:33px;border:1px solid #d9d9d9;border-radius:25px;padding:8px 18px;font:400 13.3px var(--font);outline:0;color:#000;background:#fff}
.sz-search input:focus{border-color:var(--purple)}
.sz-account{width:35px;height:35px;border-radius:50%;background:var(--purple);display:inline-flex;align-items:center;justify-content:center;color:#fff;margin-left:10px}
.sz-account svg{width:18px;height:18px}
.sz-account:hover{color:#fff;opacity:.9}
.sz-burger{width:40px;height:40px;border:0;background:none;padding:11px 7px;margin:0 -7px 0 6px;display:flex;flex-direction:column;justify-content:space-between;border-radius:8px;-webkit-tap-highlight-color:transparent}
.sz-burger span{display:block;height:2px;width:26px;background:#939598;border-radius:2px;overflow:hidden;font-size:0;transition:background .2s}
.sz-burger:hover span{background:var(--purple)}
.sz-search-btn{display:none;width:40px;height:40px;border:0;background:none;color:#333;padding:0;margin-left:auto;align-items:center;justify-content:center;border-radius:8px;-webkit-tap-highlight-color:transparent}
.sz-search-btn svg{width:23px;height:23px}
.sz-search-open .sz-search-btn{color:var(--red-t)}

.sz-menubar{background:var(--grad)}
.sz-menu .widget,.sz-menu .widget-content{margin:0}
.sz-menu .title,.sz-menu h2,.sz-menu h3{display:none}
.sz-menu .widget-content>ul{display:flex;justify-content:space-between;padding:8px 0;overflow-x:auto;scrollbar-width:none}
.sz-menu .widget-content>ul::-webkit-scrollbar{display:none}
.sz-menu .widget-content>ul>li{flex:0 0 auto;position:relative}
.sz-menu .widget-content>ul>li>a{display:block;color:#fff;font-size:15px;font-weight:700;line-height:22.5px;white-space:nowrap}
.sz-menu .widget-content>ul>li>a:hover{color:#fff;opacity:.85}
.sz-menu .widget-content>ul>li.active>a{color:#fff;box-shadow:inset 0 -2px 0 rgba(255,255,255,.9)}
.sz-menu.sz-more .widget-content>ul{-webkit-mask-image:linear-gradient(90deg,#000 82%,transparent);mask-image:linear-gradient(90deg,#000 82%,transparent)}
.sz-menu .sz-sub{display:none}

.sz-navbottom{background:#fff;padding:10px 10px 5px}
.sz-navbottom .sz-wrap{display:flex;align-items:center;gap:10px}
.sz-kanal .widget{margin:0}
.sz-kanal .title,.sz-kanal h2,.sz-kanal h3{display:none}
.sz-kanal .widget-content{display:flex;align-items:center;gap:10px}
.sz-kanal-logos{display:flex;align-items:center;gap:10px}
.sz-kanal-logos a{display:flex;align-items:center;height:34px}
.sz-kanal-logos img{max-height:37px;width:auto}
.sz-kb{flex-direction:column;justify-content:center;font-weight:900;font-size:12px;line-height:1;letter-spacing:-.2px;text-transform:uppercase;color:var(--c,#e82724)!important}
.sz-kb small{font-size:8px;font-weight:600;color:#666;letter-spacing:0;text-transform:none;margin-top:2px}
.sz-region{margin-left:auto}
.sz-region .widget{margin:0;display:flex;align-items:center;gap:10px}
.sz-region .widget-content{display:flex;align-items:center;gap:10px}
.sz-region .title,.sz-region h2,.sz-region h3{display:flex;align-items:center;gap:6px;font-size:12px;font-weight:400;color:#000;margin:0;text-transform:uppercase;white-space:nowrap}
.sz-region .title::before,.sz-region h2::before,.sz-region h3::before{content:'';width:15px;height:15px;border-radius:50%;border:4px solid #555;box-sizing:border-box}
.sz-region ul{display:flex;align-items:center;gap:14px}
.sz-region ul a{font-size:12px;font-weight:700;color:var(--ink);text-transform:uppercase;line-height:34px}
.sz-region ul a:hover{color:var(--red-t)}
.sz-regwrap{position:relative;margin-left:2px}
.sz-regbtn{display:flex;align-items:center;justify-content:center;gap:4px;width:120px;height:34px;border:0;border-radius:20px;background:var(--red-t);color:#fff;font:700 12px var(--font);text-transform:uppercase}
.sz-regbtn svg{width:14px;height:14px}
.sz-regpop{display:none;position:absolute;right:0;top:calc(100% + 16px);width:230px;background:#eee;border-radius:10px;padding:12px;z-index:30;box-shadow:0 10px 30px rgba(0,0,0,.15)}
.sz-regpop.open{display:block}
.sz-regpop ul{display:block}
.sz-regpop li a{display:block;line-height:1;padding:9px 10px;border-radius:6px;font-size:13px}
.sz-regpop li a:hover{background:#fff}

.sz-trending{background:#f5f5f5;border-bottom:1px solid #ddd}
.sz-trend .widget{margin:0;display:flex;align-items:center;gap:10px;height:45px}
.sz-trend .title,.sz-trend h2,.sz-trend h3{display:flex;align-items:center;gap:6px;font-size:14px;font-weight:600;color:var(--red-t);margin:0;white-space:nowrap;flex:0 0 auto}
.sz-trend .title svg,.sz-trend h3 svg,.sz-trend h2 svg{width:16px;height:16px}
.sz-trend .widget-content{min-width:0;flex:1;position:relative;display:flex;align-items:center}
.sz-trend ul{display:flex;align-items:center;gap:15px;overflow-x:auto;scrollbar-width:none;scroll-behavior:smooth;padding:0 36px 0 10px}
.sz-trend ul::-webkit-scrollbar{display:none}
.sz-trend li{flex:0 0 auto;font-size:14px;font-weight:500;color:#333;display:flex;align-items:center;gap:15px}
.sz-trend li+li::before{content:'|';color:#999;font-weight:400}
.sz-trend li a{color:#000;text-transform:capitalize}
.sz-trend li a:hover{color:var(--red-t)}
.sz-trend-next{position:absolute;right:0;width:28px;height:28px;border-radius:50%;border:0;background:#eee;font-size:18px;line-height:1;color:#000;display:flex;align-items:center;justify-content:center}

/* ===== DRAWER (menu samping kanan) ===== */
.sz-overlay{position:fixed;inset:0;background:rgba(0,0,0,.45);z-index:99;opacity:0;visibility:hidden;transition:opacity .25s,visibility 0s .25s;font-size:0;-webkit-tap-highlight-color:transparent}
.sz-drawer-open .sz-overlay{opacity:1;visibility:visible;transition:opacity .25s}
.sz-drawer{position:fixed;top:0;bottom:0;right:0;width:340px;max-width:88vw;background:#fff;z-index:100;transform:translateX(105%);visibility:hidden;transition:transform .3s cubic-bezier(.2,.8,.2,1),visibility 0s .3s;display:flex;flex-direction:column;box-shadow:-10px 0 40px rgba(0,0,0,.15);padding-bottom:env(safe-area-inset-bottom)}
.sz-drawer-open .sz-drawer{transform:none;visibility:visible;transition:transform .3s cubic-bezier(.2,.8,.2,1)}
.sz-drawer-open,.sz-drawer-open body{overflow:hidden}
.sz-drawer-head{display:flex;align-items:center;gap:10px;padding:12px 16px;padding-top:calc(12px + env(safe-area-inset-top));border-bottom:1px solid #eee;flex:0 0 auto}
.sz-drawer-close{width:40px;height:40px;border:0;background:#f4f4f5;border-radius:50%;display:flex;align-items:center;justify-content:center;color:#111;padding:0;flex:0 0 40px}
.sz-drawer-close svg{width:18px;height:18px}
.sz-drawer-close:hover{background:#ececee}
.sz-drawer-logo{flex:1;min-width:0;text-align:center;font-size:24px;font-weight:800;line-height:1.2;letter-spacing:-.6px;text-transform:lowercase;background:var(--grad);-webkit-background-clip:text;background-clip:text;color:transparent;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.sz-drawer-head .sz-account{display:inline-flex;margin:0;width:36px;height:36px;flex:0 0 36px}
.sz-dscroll{flex:1;overflow-y:auto;overscroll-behavior:contain;-webkit-overflow-scrolling:touch;padding:14px 16px 24px}
.sz-dsearch{display:flex;align-items:center;background:#f4f4f5;border-radius:25px;padding:0 4px 0 16px;margin-bottom:14px}
.sz-dsearch input{flex:1;min-width:0;border:0;background:transparent;height:44px;font:400 16px var(--font);outline:0;color:#000}
.sz-dsearch button{width:36px;height:36px;flex:0 0 36px;border:0;border-radius:50%;background:var(--grad);color:#fff;display:flex;align-items:center;justify-content:center;padding:0}
.sz-dsearch button svg{width:16px;height:16px}
.sz-dlabel{font-size:11px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:#9a9aa0;margin:4px 0 6px}
.sz-dmenu>li{position:relative;border-bottom:1px solid #f1f1f3}
.sz-dmenu>li:last-child{border-bottom:0}
.sz-dlink{display:flex;align-items:center;gap:12px;min-height:50px;padding:6px 44px 6px 0;font-size:15px;font-weight:600;color:#111;-webkit-tap-highlight-color:transparent}
.sz-dic{width:34px;height:34px;flex:0 0 34px;border-radius:10px;background:#fdeceb;color:var(--red-t);display:flex;align-items:center;justify-content:center;transition:.2s}
.sz-dic svg{width:19px;height:19px;fill:none;stroke:currentColor;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round}
.sz-dlink:hover{color:var(--red-t)}
.sz-dmenu li.active>.sz-dlink{color:var(--red-t)}
.sz-dmenu li.active>.sz-dlink .sz-dic{background:var(--grad);color:#fff}
.sz-dtoggle{position:absolute;right:-8px;top:5px;width:40px;height:40px;border:0;background:none;color:#777;display:flex;align-items:center;justify-content:center;border-radius:50%;padding:0}
.sz-dtoggle:hover{background:#f4f4f5}
.sz-dtoggle svg{width:20px;height:20px;transition:transform .2s}
.sz-dmenu li.open>.sz-dtoggle svg{transform:rotate(180deg)}
.sz-dmenu .sz-sub{display:none;margin:0 0 10px 16px;padding-left:28px;border-left:2px solid #f3d6d5}
.sz-dmenu li.open>.sz-sub{display:block}
.sz-dmenu .sz-sub a{display:flex;align-items:center;min-height:40px;font-size:14px;color:#555}
.sz-dmenu .sz-sub a:hover{color:var(--red-t)}
.sz-dsec{margin-top:22px}
.sz-dchips{display:flex;flex-wrap:wrap;gap:8px}
.sz-dchips a{display:inline-flex;align-items:center;min-height:36px;padding:0 14px;border-radius:20px;background:#f4f4f5;font-size:12.5px;font-weight:700;text-transform:uppercase;color:#1e1e1e}
.sz-dchips a:hover{background:var(--red);color:#fff}
.sz-dsocial ul{display:flex;gap:10px;flex-wrap:wrap}
.sz-dsocial .sz-soc{width:34px;height:34px;background:#f4f4f5;color:#333}
.sz-dsocial .sz-soc svg{width:15px;height:15px}
.sz-dsocial .sz-soc:hover{background:var(--red);color:#fff}
.sz-dfoot{margin-top:24px;padding-top:16px;border-top:1px solid #eee;display:flex;flex-wrap:wrap;gap:8px 14px;font-size:12px}
.sz-dfoot a{color:#777}

/* ===== JUDUL SEKSI ===== */
.sz-title{display:flex!important;align-items:center;gap:10px;margin:0 0 20px;font-size:21px;font-weight:700;line-height:31.5px;color:var(--ink);text-transform:none;letter-spacing:0}
.sz-title::after{content:'';flex:1;height:2px;border-radius:1px;background:linear-gradient(90deg,var(--red2) 0 20px,#ddd 20px)}
.sz-title a{color:var(--ink)}
.sz-title a:hover{color:var(--red2-t)}

/* ===== IKLAN ===== */
.sz-ads .widget{text-align:center;margin:0 auto}
.sz-ads .title,.sz-ads h2,.sz-ads h3,.sz-adw>.title,.sz-adw>h2,.sz-adw>h3{display:none!important}
.sz-ad-top{margin:20px auto 0}
.sz-ad-ph{display:flex;align-items:center;justify-content:center;background:#d9d9d9;color:#555;font-size:12px;letter-spacing:.06em;text-transform:uppercase;margin:0 auto;width:100%}
.sz-ad-ph.w970{max-width:970px;height:90px}
.sz-ad-ph.w300{max-width:300px;height:600px}
.sz-ad-ph.w300s{max-width:300px;height:250px}
.sz-ad-ph.w728{max-width:728px;height:90px}
.sz-ad-ph.w970l{max-width:970px;height:250px}
.sz-ad-ph.w336{max-width:336px;height:280px}
.sz-ad-ph.w160{width:160px;max-width:160px;height:600px}
.sz-ad-ph.w320{max-width:320px;height:50px}
/* slot iklan umum */
.sz-adslot .widget{margin:0 auto;text-align:center}
.sz-adslot .title,.sz-adslot h2,.sz-adslot h3{display:none}
.sz-adslot:empty,.sz-ads:empty{display:none}
.sz-ads .widget-content,.sz-adslot .widget-content,.sz-adw .widget-content{overflow:hidden;max-width:100%;margin:0 auto}
.sz-ad-mid{margin:30px auto 0}
.sz-ad-intop{margin:0 0 15px!important}
.sz-ads .widget:not(:has(.sz-ad-ph))::before,.sz-adslot .widget:not(:has(.sz-ad-ph))::before,.sz-adw:not(:has(.sz-ad-ph))::before{content:'Advertisement';display:block;font-size:9px;line-height:1;letter-spacing:.14em;color:#aaa;text-transform:uppercase;text-align:center;margin-bottom:5px}
.sz-only-mobile{display:none}
@media (max-width:767px){.sz-only-mobile{display:block}.sz-only-desktop{display:none!important}}
/* iklan samping kiri & kanan */
.sz-side-ad{position:fixed;top:var(--sz-adtop,220px);width:160px;z-index:20;display:none;transition:opacity .2s}
.sz-side-ad.left{right:calc(50% + 548px)}
.sz-side-ad.right{left:calc(50% + 548px)}
.sz-side-ad.sz-hide{opacity:0;pointer-events:none}
@media (min-width:1440px){.sz-side-ad{display:block}}
/* iklan sticky bawah HP */
.sz-anchor{display:none}
.sz-anchor-x{position:absolute;top:-24px;right:8px;width:30px;height:24px;border:0;border-radius:8px 8px 0 0;background:#fff;color:#555;font-size:14px;line-height:24px;padding:0;box-shadow:0 -3px 8px rgba(0,0,0,.1)}
@media (max-width:767px){
.sz-anchor{display:block;position:fixed;left:0;right:0;bottom:0;z-index:85;background:#fff;box-shadow:0 -4px 16px rgba(0,0,0,.12);padding:6px 0 calc(6px + env(safe-area-inset-bottom))}
.sz-anchor.closed,.sz-drawer-open .sz-anchor{display:none}
.sz-anchor .widget::before{display:none!important}
.sz-has-anchor body{padding-bottom:70px}
.sz-has-anchor .sz-totop{bottom:calc(84px + env(safe-area-inset-bottom))}
.sz-has-anchor .sz-next-pop{bottom:calc(76px + env(safe-area-inset-bottom))}
.sz-ad-ph.w728,.sz-ad-ph.w970{max-width:320px;height:100px;aspect-ratio:auto}
.sz-ad-ph.w970l{max-width:336px;height:280px}
}

/* ===== THUMB ===== */
.sz-thumb{display:block;position:relative;overflow:hidden;background:#eceef1}
.sz-thumb img{width:100%;height:100%;object-fit:cover}
.noimg{display:flex;align-items:center;justify-content:center;width:100%;height:100%;font-size:12px;color:#aaa}
.sz-cat{color:var(--red2-t);font-weight:700}
.sz-skel{height:220px;border-radius:12px;background:linear-gradient(90deg,#f1f1f3 25%,#e6e6ea 37%,#f1f1f3 63%);background-size:400% 100%;animation:szsk 1.4s ease infinite}
/* skeleton yang memakai ukuran asli komponen (hero/topik) supaya tinggi blok tidak melompat saat data JSON selesai dimuat -> mencegah Cumulative Layout Shift */
.sz-skel-fill{background:linear-gradient(90deg,#f1f1f3 25%,#e6e6ea 37%,#f1f1f3 63%);background-size:400% 100%;animation:szsk 1.4s ease infinite}
.sz-skel-line{display:block;width:70%;height:20px;border-radius:4px;margin-bottom:10px;background:linear-gradient(90deg,#f1f1f3 25%,#e6e6ea 37%,#f1f1f3 63%);background-size:400% 100%;animation:szsk 1.4s ease infinite}
.sz-banner-left:has(.sz-skel-line){padding-top:20px}
@keyframes szsk{0%{background-position:100% 50%}100%{background-position:0 50%}}
.sz-empty{color:var(--grey);font-size:14px}
.clamp2,.clamp3{display:-webkit-box;-webkit-box-orient:vertical;overflow:hidden}
.clamp2{-webkit-line-clamp:2}.clamp3{-webkit-line-clamp:3}

/* ===== TONTONAN (video) ===== */
.sz-movie{background:#f0f0f0;padding:25px 0 30px;margin-top:30px}
.sz-movie .widget>.title{margin-bottom:20px}
.sz-slider{position:relative}
.sz-scroller{display:flex;gap:15px;overflow-x:auto;scroll-snap-type:x mandatory;scrollbar-width:none;scroll-behavior:smooth}
.sz-scroller::-webkit-scrollbar{display:none}
.sz-mv{flex:0 0 200px;height:355px;position:relative;border-radius:12px;overflow:hidden;scroll-snap-align:start;display:block;background:#222}
.sz-mv img{width:100%;height:100%;object-fit:cover}
.sz-mv-badge{position:absolute;top:0;right:0;background:#fff;border-radius:0 0 0 10px;padding:6px 10px;display:flex;align-items:center}
.sz-mv-badge b{display:flex;align-items:center;justify-content:center;width:26px;height:18px;border-radius:5px;background:#f00;color:#fff}
.sz-mv-badge svg{width:11px;height:11px}
.sz-mv-play{position:absolute;left:80px;top:165px;width:40px;height:40px;border-radius:50%;background:rgba(0,0,0,.55);display:flex;align-items:center;justify-content:center;color:#fff}
.sz-mv-play svg{width:18px;height:18px}
.sz-mv-title{position:absolute;left:0;right:0;bottom:0;padding:40px 12px 12px;background:linear-gradient(0deg,rgba(0,0,0,.85),rgba(0,0,0,0));color:#fff;font-size:13px;font-weight:700;line-height:1.35}
.sz-mv:hover .sz-mv-title{color:#fff}
.sz-arr{position:absolute;top:50%;transform:translateY(-50%);width:38px;height:38px;border-radius:50%;border:0;background:rgba(0,0,0,.6);color:#fff;display:flex;align-items:center;justify-content:center;z-index:3}
.sz-arr.prev{left:10px}.sz-arr.next{right:10px}
.sz-arr svg{width:22px;height:22px}

/* ===== BANNER TOPIK ===== */
.sz-topik-sec .widget>.title{display:none!important}
.sz-banner{display:flex;height:250px;border-radius:12px;border:1px solid rgba(255,255,255,.1);background:linear-gradient(120deg,#fde7e7 0%,#f6e6ff 100%) center/cover no-repeat;margin:20px 0;position:relative;overflow:hidden}
.sz-banner-left{width:280px;flex:0 0 280px;display:flex;flex-direction:column;justify-content:flex-end;padding:25px}
.sz-banner-title{display:block;font-size:28px;font-weight:700;line-height:1.1;color:#000;text-transform:uppercase;max-width:230px}
.sz-banner-title:hover{color:#000;opacity:.85}
.sz-banner-right{flex:1;min-width:0;display:flex;align-items:center;position:relative;padding:0 45px}
.sz-banner-right .sz-scroller{gap:12px;padding:15px 5px}
.sz-bcard{flex:0 0 175px;height:200px;background:#fff;border-radius:var(--radius);overflow:hidden;display:flex;flex-direction:column;scroll-snap-align:start;box-shadow:0 2px 8px rgba(0,0,0,.08)}
.sz-bcard img{width:175px;height:90px;object-fit:cover}
.sz-bcard-body{padding:10px;display:flex;flex-direction:column;flex:1}
.sz-bcard-cat{font-size:9px;font-weight:800;color:var(--red2-t);text-transform:uppercase;margin-bottom:3px}
.sz-bcard h3{font-size:11px;font-weight:700;line-height:1.3;color:#1f2937;margin:0 0 4px;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
.sz-bcard-meta{font-size:9px;color:#666;margin-top:auto}
.sz-nav-btn{position:absolute;top:50%;transform:translateY(-50%);width:32px;height:32px;border-radius:50%;background:#f1f5f9;border:1px solid #e2e8f0;color:#475569;display:flex;align-items:center;justify-content:center;z-index:2}
.sz-nav-btn svg{width:14px;height:14px}
.sz-nav-btn.prev{left:8px}.sz-nav-btn.next{right:8px}

/* ===== HEADLINE ===== */
.sz-hl{display:flex;gap:25px;align-items:flex-start}
.sz-hl-main{flex:1;min-width:0}
.sz-hl-side{width:300px;flex:0 0 300px;padding-top:0}
.sz-b-hero{background:transparent;padding:0}
/* Headline gaya VIVA: 1 besar (slider) + 2x2 kotak bergambar */
.sz-hl-top{margin-top:20px}
.sz-viva{display:flex;flex-direction:column;gap:4px;border-radius:var(--radius);overflow:hidden;background:#fff}
.sz-viva .sz-hs{border-radius:0}
.sz-viva .sz-hero-frame{height:400px;border-radius:0}
.sz-viva .sz-hero-tint{padding:60px 28px 26px;padding-right:140px;background:linear-gradient(0deg,rgba(0,0,0,.95) 0,rgba(0,0,0,.6) 55%,rgba(0,0,0,0) 100%)}
.sz-viva .sz-hero-title{font-size:27px;line-height:1.3;font-weight:800;margin-bottom:12px;text-shadow:0 1px 2px rgba(0,0,0,.35);display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
.sz-viva-grid{display:grid;grid-template-columns:1fr 1fr;gap:4px}
.sz-vt{position:relative;display:block;overflow:hidden;aspect-ratio:16/9;background:#222;color:#fff}
.sz-vt img{width:100%;height:100%;object-fit:cover;transition:transform .5s ease}
.sz-vt:hover img,.sz-viva .sz-hero-frame:hover img{transform:scale(1.04)}
.sz-viva .sz-hero-frame img{transition:transform .5s ease}
.sz-vt-in{position:absolute;left:0;right:0;bottom:0;padding:50px 18px 16px;background:linear-gradient(0deg,rgba(0,0,0,.95) 0,rgba(0,0,0,.6) 55%,rgba(0,0,0,0) 100%)}
.sz-vt h3{font-size:18px;line-height:1.35;font-weight:800;color:#fff;margin:0 0 8px;text-shadow:0 1px 2px rgba(0,0,0,.35);display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
.sz-vt:hover h3,.sz-viva .sz-hero-frame:hover .sz-hero-title{color:#fff;text-decoration:underline;text-decoration-thickness:1px;text-underline-offset:3px}
.sz-vmeta{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.sz-vtag{display:inline-block;background:#3a3a3a;color:#fff;font-size:10.5px;font-weight:700;line-height:1;padding:4px 7px;border-radius:3px}
.sz-vmeta time{font-size:11.5px;color:#ddd;font-weight:500}
.sz-hl-badge{position:absolute;left:16px;top:16px;z-index:2;display:inline-flex;align-items:center;gap:5px;background:var(--red-t,#c5211f);color:#fff;font-size:11px;font-weight:800;letter-spacing:.04em;text-transform:uppercase;line-height:1;padding:6px 10px;border-radius:3px;box-shadow:0 2px 6px rgba(0,0,0,.25)}
.sz-hl-badge::before{content:'';width:6px;height:6px;border-radius:50%;background:#fff;flex:0 0 6px}
.sz-b-hero>.title{display:none!important}
.sz-hero-frame{display:block;position:relative;border-radius:12px;overflow:hidden;height:413px;background:#ddd}
.sz-hs{position:relative;border-radius:12px;overflow:hidden;background:#ddd;isolation:isolate}
.sz-hs-track{display:flex;transition:transform .55s cubic-bezier(.25,.8,.25,1);will-change:transform;touch-action:pan-y}
.sz-hs-slide{flex:0 0 100%;min-width:0;border-radius:0}
.sz-hs .sz-hero-tint{padding-right:150px}
.sz-hs-arr{position:absolute;top:50%;transform:translateY(-50%);width:40px;height:40px;border-radius:50%;border:0;background:rgba(255,255,255,.92);color:#111;display:flex;align-items:center;justify-content:center;z-index:3;opacity:0;transition:opacity .2s,background .2s;box-shadow:0 2px 10px rgba(0,0,0,.2);padding:0}
.sz-hs-arr svg{width:22px;height:22px}
.sz-hs-arr.prev{left:14px}.sz-hs-arr.next{right:14px}
.sz-hs:hover .sz-hs-arr,.sz-hs-arr:focus-visible{opacity:1}
.sz-hs-arr:hover{background:#fff;color:var(--red-t)}
.sz-hs-dots{position:absolute;right:20px;bottom:28px;display:flex;gap:0;z-index:3}
.sz-hs-dots button{position:relative;width:24px;height:24px;border:0;padding:0;background:none;cursor:pointer}
.sz-hs-dots button::before{content:'';position:absolute;top:8px;right:4px;width:8px;height:8px;border-radius:8px;background:rgba(255,255,255,.55);transition:width .3s,background .3s}
.sz-hs-dots button.on{width:38px}
.sz-hs-dots button.on::before{width:22px;background:#fff}
.sz-hs-bar{position:absolute;left:0;right:0;bottom:0;height:3px;background:rgba(255,255,255,.18);z-index:3}
.sz-hs-bar i{display:block;height:100%;width:0;background:var(--grad)}
.sz-hero-frame img{width:100%;height:100%;object-fit:cover}
.sz-hero-tint{position:absolute;left:0;right:0;bottom:0;padding:30px;background:linear-gradient(0deg,rgba(0,0,0,.95) 0,rgba(0,0,0,.4) 60%,rgba(0,0,0,0) 100%)}
.sz-hero-title{font-size:26px;font-weight:800;line-height:1.2;color:#fff;margin-bottom:15px}
.sz-hero-frame:hover .sz-hero-title{color:#fff;text-decoration:underline}
.sz-hero-meta{display:flex;align-items:center;gap:12px}
.sz-tag{display:inline-block;background:#f0f0f0;border-radius:6px;font-size:11px;font-weight:700;line-height:16.5px;color:#111;padding:4px 12px}
.sz-hero-date{font-size:12px;color:#ddd}
.sz-hub-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-top:25px;padding:0 0 10px}
.sz-hub-item{display:flex;gap:15px;align-items:flex-start}
.sz-hub-item .sz-thumb{width:130px;height:85px;flex:0 0 130px;border-radius:var(--radius)}
.sz-hub-item h3{font-size:14px;font-weight:700;line-height:19.6px;color:var(--ink)}
.sz-hub-item h3 a{display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
.sz-mini-cat{display:block;font-size:12px;font-weight:800;color:#666;margin-top:8px}

/* ===== TERKINI + BOX OREN ===== */
.sz-latest{display:grid;grid-template-columns:minmax(0,1fr) 261px;gap:30px;align-items:start}
.sz-li-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}
.sz-li{display:flex;gap:12px;align-items:flex-start}
.sz-li .sz-thumb{width:120px;height:100px;flex:0 0 120px;border-radius:var(--radius)}
.sz-li-meta{font-size:13px;font-weight:700;line-height:19.5px;color:var(--red2-t);margin-bottom:4px}
.sz-li-meta span{font-weight:400;color:var(--grey)}
.sz-li h3{font-size:14px;font-weight:600;line-height:21px;color:var(--ink)}
.sz-li h3 a{display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
.sz-b-sidelist{background:#c2410c;border-radius:8px;padding:20px}
.sz-b-sidelist>.sz-title,.sz-b-sidelist>.sz-title a{color:#fff;font-size:21px}
.sz-b-sidelist>.sz-title::after{background:rgba(255,255,255,.2)}
.sz-ys-list{display:flex;flex-direction:column;gap:15px}
.sz-ys{display:flex;gap:12px;align-items:center}
.sz-ys .sz-thumb{width:80px;height:80px;flex:0 0 80px;border-radius:50%}
.sz-ys a.sz-ys-t{display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden;font-size:13px;font-weight:600;line-height:19.5px;color:#fff}
.sz-ys a.sz-ys-t:hover{color:#fff;text-decoration:underline}
.sz-ys span{display:block;font-size:12px;color:#fff;margin-top:4px}

/* ===== KASIH PAHAM (besar + 3) ===== */
.sz-kp{display:grid;grid-template-columns:minmax(0,653px) minmax(0,1fr);gap:20px;margin-top:30px}
.sz-kp-main .sz-thumb{height:366px}
.sz-kp-main h3{font-size:18.72px;font-weight:700;line-height:28.08px;color:var(--ink);margin-top:10px}
.sz-kp-sec{display:grid;gap:15px;align-content:start}
.sz-kp-item{display:grid;grid-template-columns:160px 1fr;grid-template-rows:auto 1fr;align-items:start;column-gap:12px;row-gap:6px;padding-bottom:13px;border-bottom:1px solid #dedede}
.sz-kp-item:last-child{border-bottom:0}
.sz-kp-item .sz-thumb{width:160px;height:120px;border-radius:var(--radius);grid-row:span 2}
.sz-kp-item h4{font-size:14px;font-weight:600;line-height:21px;color:var(--ink)}
.sz-kp-item h4 a{display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
.sz-time{font-size:12px;color:var(--grey);line-height:18px}

/* ===== KONTEN UTAMA ===== */
.sz-content{display:grid;grid-template-columns:minmax(0,745px) 300px;gap:30px;margin-top:30px;align-items:start}
.sz-main{min-width:0}
.sz-blocks .widget{margin-bottom:30px}
.sz-side{min-width:0;align-self:stretch;display:flex;flex-direction:column;gap:30px}
.sz-side>.section{display:flex;flex-direction:column;gap:30px}
.sz-side>.section:empty{display:none}
.sz-side>.sz-side-sticky{flex:1}
.sz-side>.sz-side-sticky>.widget{position:sticky;top:85px}
.sz-side .widget>.title,.sz-side .widget>h2,.sz-side .widget>h3{font-size:21px;font-weight:700;color:var(--ink);margin:0 0 15px}

/* pink */
.sz-b-pink{background:#f5e4e4;border-radius:8px;padding:20px}
.sz-b-pink>.title{display:none!important}
.sz-pink-top{display:grid;grid-template-columns:290px minmax(0,1fr);gap:10px}
.sz-pink-bot{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:20px}
.sz-pi{border-radius:8px;overflow:hidden}
.sz-brand{display:flex;align-items:center;justify-content:center;border-radius:6px;color:#fff;font-weight:900;text-transform:lowercase;letter-spacing:-.5px;background:var(--bc,#e82724)}
.sz-pink-top .sz-brand{height:96px;font-size:26px}
.sz-pink-bot .sz-brand{height:55px;font-size:18px}
.sz-pi-photo{height:115px;border-radius:var(--radius)}
.sz-pi-big{height:227px;border-radius:var(--radius)}
.sz-pi-body{padding:8px 12px 14px}
.sz-pi-meta{display:flex;gap:6px;font-size:12px;line-height:18px;color:#5c5c5c;margin-bottom:5px}
.sz-pi-meta b{color:var(--red2-t);text-transform:uppercase;font-weight:700}
.sz-pi-title{font-size:13px;font-weight:600;line-height:18.85px;color:#111;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}

/* bisnis (featured) */
.sz-feat{display:grid;grid-template-columns:336px minmax(0,1fr);gap:25px;align-items:center}
.sz-feat .sz-thumb{height:188px}
.sz-lbl{font-size:14px;font-weight:700;line-height:21px;color:var(--red2-t)}
.sz-feat h2{font-size:17px;font-weight:600;line-height:25.5px;color:var(--ink);margin:10px 0}
.sz-feat .sz-time{font-size:13px}
.sz-feat-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:30px}
.sz-fg .sz-thumb{height:180px;border-radius:var(--radius);margin-bottom:10px}
.sz-fg h3{font-size:13px;font-weight:700;line-height:19.5px;color:var(--red2-t)}
.sz-fg h3 span{font-weight:400;color:#555558}
.sz-fg h2{font-size:14px;font-weight:600;line-height:21px;color:var(--ink);margin-top:4px}
.sz-fg h2 a{display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}

/* suara mereka */
.sz-sm-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:26px}
.sz-sm .sz-thumb{height:250px;border-radius:var(--radius);margin-bottom:10px}
.sz-sm h3{font-size:14px;font-weight:300;line-height:21px;color:var(--ink)}
.sz-sm h2{font-size:14px;font-weight:600;line-height:21px;color:var(--ink);margin-top:8px}
.sz-sm h2 a{display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}

/* hijau */
.sz-b-green{background:#ddf0e9;border-radius:6px;padding:30px 20px 20px}
.sz-b-green>.sz-title::after{background:linear-gradient(90deg,var(--red2) 0 20px,#fff 20px)}
.sz-gr-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}
.sz-gr{display:grid;grid-template-columns:120px 1fr;gap:15px}
.sz-gr .sz-thumb{height:90px;border-radius:var(--radius)}
.sz-gr h3{font-size:14px;font-weight:600;line-height:21px;color:var(--ink)}
.sz-gr h3 a{display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
.sz-gr .sz-time{font-size:13px;display:block;margin-top:4px}

/* list kanal (index + terkait) */
.sz-kl-list{display:flex;flex-direction:column;gap:25px}
.sz-kl{display:flex;gap:20px;padding-bottom:20px;border-bottom:1px solid #eee}
.sz-kl .sz-thumb{width:250px;height:140px;flex:0 0 250px;border-radius:var(--radius)}
.sz-kl-info{min-width:0;flex:1}
.sz-kl-t{font-size:14px;font-weight:600;line-height:21px;color:var(--ink);margin-bottom:8px}
.sz-kl-t a{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.sz-kl-cat{font-size:14px;font-weight:700;line-height:19.6px;color:#d60000}
.sz-kl-cat a{color:#d60000}
.sz-kl-cat span{font-size:13px;font-weight:300;color:var(--grey)}
.sz-pipe{font-style:normal}
.sz-more-wrap{text-align:center;margin:30px 0 0}
.sz-loadmore{display:inline-flex;align-items:center;justify-content:center;padding:10px 34px;border-radius:25px;background:var(--grad);color:#fff!important;font-weight:700;font-size:14px}
.sz-loadmore:hover{opacity:.9}
.sz-loadmore.loading{opacity:.6;pointer-events:none}
.sz-pagetitle{margin-bottom:25px}
/* ===== INDEKS / SITEMAP ===== */
.sz-ix{display:flex;flex-direction:column;gap:18px;margin-bottom:30px}
.sz-ix:empty{display:none}
.sz-ix-top{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:12px}
.sz-ix-sum{margin:0;font-size:13px;color:var(--grey)}
.sz-ix-sum b{color:var(--ink)}
.sz-ix-tabs{display:inline-flex;background:var(--soft);border:1px solid var(--line);border-radius:30px;padding:3px}
.sz-ix-tabs button{border:0;background:none;font:700 13px var(--font);color:var(--grey);padding:8px 16px;border-radius:30px;cursor:pointer}
.sz-ix-tabs button[aria-selected=true]{background:var(--grad);color:#fff}
.sz-ix-bar{display:flex;align-items:center;gap:12px;border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:10px 0}
.sz-ix-chips{display:flex;gap:8px;overflow-x:auto;flex:1;min-width:0;scrollbar-width:none;padding:2px 0}
.sz-ix-chips::-webkit-scrollbar{display:none}
.sz-ix-chip{flex:0 0 auto;border:1px solid var(--line);background:#fff;color:var(--ink);font:600 13px var(--font);padding:6px 12px;border-radius:20px;cursor:pointer;white-space:nowrap}
.sz-ix-chip i{font-style:normal;color:var(--grey);font-weight:500;margin-left:4px}
.sz-ix-chip[aria-pressed=true]{background:var(--red2-t);border-color:var(--red2-t);color:#fff}
.sz-ix-chip[aria-pressed=true] i{color:rgba(255,255,255,.8)}
.sz-ix-date{display:flex;align-items:center;gap:6px;flex:0 0 auto;font-size:12px;color:var(--grey)}
.sz-ix-date input{font:600 13px var(--font);color:var(--ink);border:1px solid var(--line);border-radius:8px;padding:6px 8px;background:#fff}
.sz-ix-day{display:flex;flex-direction:column}
.sz-ix-dh{position:sticky;top:60px;z-index:2;display:flex;align-items:baseline;gap:8px;margin:0;padding:10px 0;background:var(--bg);font-size:15px;font-weight:700;color:var(--ink);border-bottom:2px solid var(--ink)}
.sz-ix-dh .n{margin-left:auto;font-size:12px;font-weight:600;color:var(--grey)}
.sz-ix-list{list-style:none;margin:0;padding:0}
.sz-ix-it{display:grid;grid-template-columns:52px minmax(0,1fr) 96px;gap:14px;align-items:start;padding:14px 0;border-bottom:1px solid var(--line)}
.sz-ix-it time{font-size:13px;font-weight:700;color:var(--red2-t);font-variant-numeric:tabular-nums;padding-top:2px}
.sz-ix-it .sz-cat{display:inline-block;font-size:12px;margin-bottom:3px}
.sz-ix-t{display:block;font-size:15px;font-weight:700;line-height:1.45;color:var(--ink);overflow-wrap:break-word}
.sz-ix-t:hover{color:var(--red2-t)}
.sz-ix-it .sz-thumb{width:96px;height:64px;border-radius:6px}
.sz-ix-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}
.sz-ix-card{border:1px solid var(--line);border-radius:var(--radius);padding:14px 16px;display:flex;flex-direction:column;gap:6px;min-width:0;background:#fff}
.sz-ix-ch{display:flex;align-items:center;gap:8px;margin:0 0 4px;font-size:16px;font-weight:700}
.sz-ix-ch a{color:var(--ink)}
.sz-ix-ch .n{font-size:11px;font-weight:700;color:#fff;background:var(--grad);border-radius:10px;padding:2px 8px}
.sz-ix-ch .all{margin-left:auto;font-size:12px;font-weight:600;color:var(--red2-t)}
.sz-ix-card ol{margin:0;padding:0;list-style:none;display:flex;flex-direction:column}
.sz-ix-card li{display:flex;gap:10px;padding:7px 0;border-top:1px dashed var(--line);font-size:13.5px;line-height:1.4}
.sz-ix-card li:first-child{border-top:0}
.sz-ix-card li a{color:var(--ink);font-weight:600;min-width:0;overflow-wrap:break-word}
.sz-ix-card li a:hover{color:var(--red2-t)}
.sz-ix-card li time{flex:0 0 auto;margin-left:auto;font-size:11.5px;color:var(--grey);white-space:nowrap;padding-top:1px}
.sz-ix-x{align-self:flex-start;border:0;background:none;padding:4px 0 0;font:700 12.5px var(--font);color:var(--red2-t);cursor:pointer}
.sz-ix-empty{padding:30px 16px;text-align:center;color:var(--grey);font-size:14px;background:var(--soft);border-radius:var(--radius)}
.sz-ix-empty button{margin-top:10px}
.sz-ix-more{text-align:center}
.sz-ix-more button{border:0;cursor:pointer;font-family:var(--font)}
.sz-ix-skel{height:64px;border-radius:6px;background:linear-gradient(90deg,#f0f0f0,#e6e6e6,#f0f0f0);background-size:200% 100%;animation:szsk 1.2s infinite linear}
@keyframes szsk{to{background-position:-200% 0}}
@media (prefers-reduced-motion:reduce){.sz-ix-skel{animation:none}}
@media (max-width:767px){
 .sz-ix-bar{flex-direction:column;align-items:stretch}
 .sz-ix-date{justify-content:space-between}
 .sz-ix-it{grid-template-columns:44px minmax(0,1fr) 78px;gap:10px}
 .sz-ix-it .sz-thumb{width:78px;height:52px}
 .sz-ix-t{font-size:14px}
 .sz-ix-grid{grid-template-columns:minmax(0,1fr)}
 .sz-ix-dh{top:56px}
}
.sz-404{text-align:center;padding:60px 0}
.sz-404 b{display:block;font-size:72px;color:var(--red-t);line-height:1}
.sz-404 h1{font-size:24px;margin:10px 0}
.sz-404 p{color:#555;margin-bottom:20px}

/* ===== SIDEBAR ===== */
.sz-b-diskusi>.title,.sz-b-diskusi>h3{display:block!important;font-size:24px!important;font-weight:700;line-height:36px;color:#000!important;margin:0 0 15px!important}
.sz-b-diskusi>.title::after{display:none}
.sz-dk-list{display:flex;flex-direction:column;gap:15px}
.sz-dk{display:flex;gap:10px}
.sz-dk-n{width:25px;height:25px;flex:0 0 25px;border-radius:50%;background:#111;color:#fff;font-size:14px;font-weight:300;line-height:25px;text-align:center}
.sz-dk h3{font-size:13px;font-weight:600;line-height:18.85px;color:#111}
.sz-dk h3 a{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.sz-dk-meta{display:flex;align-items:center;gap:10px;font-size:12px;color:#666;margin-top:5px}
.sz-dk-meta svg{width:15px;height:15px;color:#888}
.sz-b-darkbox{background:#333;padding:15px}
.sz-side .sz-b-darkbox>.sz-title,.sz-b-darkbox>.sz-title{font-size:16px;line-height:24px;margin:10px 0 20px;color:#fff}
.sz-b-darkbox>.sz-title a{color:#fff}
.sz-b-darkbox>.sz-title::after{height:3px;background:#1e1e1e}
.sz-db .sz-thumb{height:151px;border-radius:var(--radius);margin-bottom:5px}
.sz-db h3{font-size:14px;font-weight:600;line-height:18.2px;color:#fff;margin-bottom:5px}
.sz-db h3 a:hover{color:#fff;text-decoration:underline}
.sz-db span{font-size:12px;color:#bbb}
.sz-pop-h{display:flex;align-items:center;gap:6px;font-size:18px;font-weight:700;line-height:27px;color:#000;text-transform:uppercase;margin:0}
.sz-pop-h svg{width:20px;height:20px;color:var(--red-t)}
.sz-pop-item{padding:10px 5px 10px 0;border-bottom:1px solid #ddd}
.sz-pop-item h3{font-size:14px;font-weight:600;line-height:21px;color:var(--ink)}
.sz-pop-item h3 a{display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
.sz-pop-meta{display:block;font-size:13px;font-weight:700;line-height:19.5px;color:var(--red2-t);margin-top:4px}
.sz-pop-meta i{font-style:normal;font-size:12px;font-weight:400;color:#555558}
.sz-side .Label ul{display:flex;flex-wrap:wrap;gap:8px}
.sz-side .Label li a{display:inline-block;font-size:13px;padding:6px 12px;border-radius:6px;background:var(--grad);color:#fff}
.sz-side .Label .label-count{opacity:.7;margin-left:3px}

/* ===== ARTIKEL ===== */
.sz-breadcrumb{display:flex;flex-wrap:wrap;gap:8px;font-size:14px;line-height:21px;color:var(--grey);margin:20px 0 15px}
.sz-breadcrumb a{color:#555}
.sz-breadcrumb a:hover{color:var(--red2-t)}
.sz-breadcrumb .sep{color:var(--grey)}
.sz-detail{display:flex;gap:30px;align-items:flex-start}
.sz-detail .sz-main{flex:1;min-width:0;max-width:745px}
.sz-detail .sz-side{width:300px;flex:0 0 300px;align-self:stretch}
.sz-article-title{font-size:var(--title-size);font-weight:700;line-height:1.5;color:var(--ink);overflow-wrap:break-word;word-break:break-word}
.sz-profile{display:flex;align-items:center;gap:5px;min-height:0;padding:12px 0 4px;flex-wrap:wrap}
.sz-profile+.sz-date{margin:0 0 12px 40px}
.sz-date+.sz-toolbar{margin:0}
.sz-avatar{width:30px;height:30px;border-radius:50%;object-fit:cover;background:#eee;display:flex;align-items:center;justify-content:center;color:#aaa}
.sz-avatar svg{width:18px;height:18px}
.sz-author{font-size:13px;font-weight:700;color:var(--grey);margin-left:5px}
.sz-share{display:flex;gap:2px;margin-left:auto}
.sz-sh{width:34px;height:34px;border-radius:50%;display:inline-flex;align-items:center;justify-content:center;color:#fff;border:0;padding:0}
.sz-sh i{width:30px;height:30px;border-radius:50%;display:flex;align-items:center;justify-content:center}
.sz-sh svg{width:15px;height:15px}
.sz-sh.fb i{background:#1877f2}.sz-sh.wa i{background:#25d366}.sz-sh.x i{background:#000}.sz-sh.tg i{background:#229ed9}.sz-sh.link i{background:#8a8a8a}
.sz-sh:hover{color:#fff;opacity:.85}
.sz-date{display:block;font-size:13px;line-height:19.5px;color:var(--grey)}
.sz-cover{margin:20px 0 10px}
.sz-cover img{width:100%;max-height:419px;object-fit:cover;border-radius:var(--radius)}
.sz-cover figcaption{background:#ebebeb;padding:7px 10px;font-size:12px;line-height:18px;color:#555;text-align:left}
.sz-cover figcaption a{color:var(--red-t);text-decoration:none}
.sz-cover figcaption a:hover{text-decoration:underline}
/* ===== TOOLBAR ARTIKEL: Dengarkan Berita + Ukuran Teks ===== */
.sz-toolbar{display:flex;flex-wrap:wrap;align-items:center;gap:14px;background:var(--soft);border:1px solid var(--line);border-radius:var(--radius);padding:12px 16px;margin:4px 0 18px}
.sz-tts{display:flex;align-items:center;gap:10px;flex:1;min-width:230px}
.sz-tts-btn{display:inline-flex;align-items:center;gap:8px;background:var(--grad);color:#fff;border:0;border-radius:30px;padding:9px 18px 9px 14px;font-size:13.5px;font-weight:700;font-family:var(--font);cursor:pointer;white-space:nowrap}
.sz-tts-btn svg{width:17px;height:17px;flex:0 0 17px}
.sz-tts-btn:hover{opacity:.92}
.sz-tts-btn.sz-hide{display:none}
.sz-tts-mini{display:none;align-items:center;gap:8px;flex:1;min-width:0}
.sz-tts-mini.show{display:flex}
.sz-tts-mini button{width:32px;height:32px;border-radius:50%;border:0;background:#fff;box-shadow:0 1px 3px rgba(0,0,0,.18);display:flex;align-items:center;justify-content:center;color:var(--ink);cursor:pointer;flex:0 0 32px;padding:0}
.sz-tts-mini button svg{width:15px;height:15px}
.sz-tts-mini button .ic-play{display:none}
.sz-tts-mini.paused #sz-tts-pp .ic-pause{display:none}
.sz-tts-mini.paused #sz-tts-pp .ic-play{display:block}
.sz-tts-track{flex:1;height:4px;background:#e2e2e6;border-radius:3px;overflow:hidden;min-width:50px}
.sz-tts-track i{display:block;height:100%;width:0;background:var(--grad);transition:width .25s linear}
.sz-tts-rate{border:1px solid var(--line);border-radius:6px;padding:5px 6px;font-size:12px;background:#fff;color:var(--ink);font-family:var(--font)}
/* ===== VIEWS ARTIKEL ===== */
.sz-views{display:flex;align-items:center;gap:6px;flex:0 0 auto;color:var(--grey);font-size:13px;font-weight:600;white-space:nowrap}
.sz-views svg{width:18px;height:18px;flex:0 0 18px;fill:#9a9a9a}
/* ===== UKURAN TEKS (ikon saja, tanpa label tulisan) ===== */
.sz-fontsize{display:flex;align-items:center;gap:6px;flex:0 0 auto;margin-left:auto}
.sz-fs-btn{width:30px;height:30px;border-radius:50%;border:1px solid var(--line);background:#fff;color:var(--ink);font-size:12.5px;font-weight:800;font-family:var(--font);cursor:pointer;display:flex;align-items:center;justify-content:center;padding:0}
.sz-fs-btn.active{background:var(--ink);color:#fff;border-color:var(--ink)}
.sz-post-body.sz-fs-s{font-size:14px;line-height:24px}
.sz-post-body.sz-fs-l{font-size:19px;line-height:32px}
/* ===== SUKA ARTIKEL ===== */
.sz-likebox{display:flex;justify-content:center;margin:0 0 24px}
.sz-like-btn{display:inline-flex;align-items:center;gap:8px;background:#fff;border:1.5px solid var(--line);border-radius:30px;padding:10px 22px;font-size:14px;font-weight:700;font-family:var(--font);color:var(--ink);cursor:pointer}
.sz-like-btn svg{width:19px;height:19px;flex:0 0 19px;fill:none;stroke:#9a9a9a;stroke-width:1.8;transition:fill .15s,stroke .15s}
.sz-like-btn .sz-like-label{color:var(--grey);font-weight:600}
.sz-like-btn.active{border-color:#e8273f;background:#fff5f6}
.sz-like-btn.active svg{fill:#e8273f;stroke:#e8273f}
.sz-like-btn .sz-like-pop-ic{display:inline-flex}
.sz-like-btn.sz-like-anim svg{animation:szLikePop .3s ease}
@keyframes szLikePop{0%{transform:scale(1)}45%{transform:scale(1.4)}100%{transform:scale(1)}}
/* ===== IKLAN PARALLAX DALAM ARTIKEL ===== */
/* Teknik: .sz-pxad-win (ruang statis di alur halaman) membungkus .sz-pxad-clip
   (clip-path:inset = jendela yang ikut scroll) membungkus .sz-pxad-layer
   (position:fixed = 'backdrop' diam di layar). Saat discroll, jendela bergerak
   naik mengikuti halaman sementara backdrop di baliknya diam di viewport --
   efek parallax asli, 100% CSS, tanpa JS per-frame, mulus di HP. */
.sz-pxad-win{position:relative;width:min(300px,100%);aspect-ratio:6/5;margin:0 auto;border-radius:8px;box-shadow:0 0 0 1px var(--line);background:#d9d9d9}
.sz-pxad-clip{position:absolute;inset:0;clip:rect(0,auto,auto,0);clip-path:inset(0 round 8px)}
.sz-pxad-layer{position:fixed;top:0;bottom:0;left:0;width:100%;display:flex;align-items:center;justify-content:center;background:linear-gradient(135deg,#8d8d8d,#c7c7c7)}
.sz-pxad-ph{color:#fff;font-size:12px;letter-spacing:.06em;text-transform:uppercase;text-shadow:0 1px 3px rgba(0,0,0,.45)}
/* fallback: JS nonaktif/mati, prefers-reduced-motion, atau browser lawas tanpa clip-path */
.sz-pxad-static .sz-pxad-win{height:auto}
.sz-pxad-static .sz-pxad-clip{position:static;clip:auto;clip-path:none}
.sz-pxad-static .sz-pxad-layer{position:static;height:auto;aspect-ratio:6/5;border-radius:8px}
@supports not (clip-path:inset(0)){
 .sz-pxad-win{height:auto}
 .sz-pxad-clip{position:static;clip:auto}
 .sz-pxad-layer{position:static;height:auto;aspect-ratio:6/5;border-radius:8px}
}
.sz-post-body{font-size:var(--body-size);line-height:1.8;color:var(--ink);overflow-wrap:break-word;margin-top:10px}
.sz-post-body p{margin:0 0 20px}
.sz-post-body h2{font-size:24px;font-weight:700;line-height:1.4;color:#000;margin:10px 0 20px}
.sz-post-body h3{font-size:20px;font-weight:700;line-height:1.4;color:#000;margin:10px 0 16px}
.sz-post-body a{color:var(--link)}
.sz-post-body img{margin:0 auto;border-radius:6px}
.sz-post-body .separator a{margin-left:0!important;margin-right:0!important}
.sz-post-body .tr-caption-container{width:100%!important;margin:0 0 20px!important;padding:0}
.sz-post-body .tr-caption{font-size:12px;line-height:18px;color:#555;background:#ebebeb;padding:7px;text-align:left!important}
.sz-post-body blockquote{border-left:4px solid var(--red2);background:var(--soft);margin:0 0 20px;padding:15px 20px;font-style:italic}
.sz-post-body ul,.sz-post-body ol{padding-left:20px;margin:0 0 20px;list-style:disc}
.sz-post-body ol{list-style:decimal}
.sz-post-body iframe{max-width:100%}.sz-post-body iframe.sz-content-embed{width:100%;aspect-ratio:16/9;height:auto;border:0}
.sz-post-body table:not(.tr-caption-container){width:100%;border-collapse:collapse;font-size:15px;margin-bottom:20px}
.sz-post-body table:not(.tr-caption-container) td,.sz-post-body table:not(.tr-caption-container) th{border:1px solid #ddd;padding:8px}
.sz-tablewrap{overflow-x:auto;-webkit-overflow-scrolling:touch;margin-bottom:20px}
.sz-tablewrap table{margin-bottom:0!important;min-width:480px}
.sz-tensec{display:flex;gap:4px;background:var(--soft);padding:30px;margin:0 0 20px}
.sz-tensec-ic{width:110px;flex:0 0 110px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;color:var(--red2-t);font-size:12px;font-weight:800;text-align:center;line-height:1.2}
.sz-tensec-ic svg{width:60px;height:60px}
.sz-post-body .sz-tensec ul{border-left:1px solid #cfcfcf;padding:0 0 0 50px;margin:0;list-style:disc}
.sz-post-body .sz-tensec li{font-size:16px;line-height:24px;color:#000;margin-bottom:10px}
.sz-post-body .sz-tensec li:last-child{margin-bottom:0}
.sz-bj{display:flex;gap:20px;background:var(--soft);padding:20px;margin:0 0 20px;align-items:center}
.sz-bj-ic{width:95px;flex:0 0 95px;padding:10px 20px 10px 10px}
.sz-bj-ic .sz-thumb{width:64px;height:48px;border-radius:6px}
.sz-bj-h{font-size:16px;color:var(--red-t);line-height:28.8px}
.sz-post-body .sz-bj ul{list-style:none;padding:0;margin:0}
.sz-post-body .sz-bj li a{font-size:15px;font-weight:700;line-height:22.5px;color:#222}
.sz-post-body .sz-bj li a:hover{color:var(--red-t)}
#ikuti-saluran .widget>.title,#ikuti-saluran .widget>h2,#ikuti-saluran .widget>h3{display:none}
.sz-follow{background:#f8f9fa;border:1px solid #e9ecef;border-radius:12px;padding:16px;margin:30px 0 20px;text-align:center}
.sz-follow-t{font-size:13px;font-weight:700;color:#6c757d;text-transform:uppercase;margin-bottom:12px}
.sz-follow-btns{display:flex;justify-content:center;gap:12px;flex-wrap:wrap}
.sz-fbtn{display:inline-flex;align-items:center;justify-content:center;gap:8px;width:240px;max-width:100%;padding:10px 20px;border-radius:30px;font-size:14px;font-weight:600;border:1px solid #dadce0;background:#fff;color:#3c4043}
.sz-fbtn.wa{background:#25d366;border-color:#25d366;color:#fff}
.sz-fbtn svg{width:18px;height:18px}
.sz-fbtn:hover{opacity:.9}
.sz-sharebox{display:flex;align-items:center;gap:5px;background:var(--soft);border-radius:6px;padding:10px;margin-top:20px}
.sz-sharebox h4{font-size:16px;font-weight:700;line-height:24px;color:#000}
.sz-tagsbox{background:var(--soft);border-radius:6px;padding:20px;margin-top:20px}
.sz-tagsbox .sz-title{margin:10px 0 14px}
.sz-tagsbox a.sz-tg{display:inline-block;margin:5px 5px 0 0;padding:6px 12px;border-radius:6px;background:var(--grad);color:#fff;font-size:13px;line-height:19.5px}
.sz-tagsbox a.sz-tg:hover{color:#fff;opacity:.9}
.sz-post-sec{margin-top:30px}
/* ===== KOMENTAR ===== */
.sz-comments{margin-top:30px;background:var(--soft);border:1px solid var(--line);border-radius:var(--radius);padding:18px 20px 20px}
.sz-comments .sz-title{margin:0 0 14px;font-size:18px}
#comments.comments{font-family:var(--font)}
#comments h3.title{margin:0 0 14px;font-size:13px;font-weight:600;color:var(--grey)}
#comments h3.title a{color:inherit;text-decoration:none}
#comments #Blog1_comments-block-wrapper{margin-bottom:16px}
#comments #comments-block,#comments ol.comment-thread{list-style:none;margin:0;padding:0}
#comments li.comment{margin-bottom:12px}
#comments .comment-block{background:#fff;border:1px solid var(--line);border-radius:10px;padding:14px 16px;position:relative}
#comments .comment-header{display:flex;align-items:center;flex-wrap:wrap;gap:8px 10px;margin-bottom:6px}
#comments .avatar-image-container{width:34px;height:34px;border-radius:50%;overflow:hidden;flex:0 0 34px}
#comments .avatar-image-container img{width:100%;height:100%;object-fit:cover}
#comments cite.user{font-style:normal;font-weight:700;font-size:14px;color:var(--ink)}
#comments cite.user a{color:inherit;text-decoration:none}
#comments cite.user a:hover{color:var(--red-t)}
#comments .icon.blog-author{display:inline-block;padding:1px 8px;font-size:10px;font-weight:700;line-height:1.6;color:#fff;background:var(--grad);border-radius:20px}
#comments .datetime.secondary-text{font-size:12px;color:var(--grey);margin-left:auto}
#comments .datetime.secondary-text a{color:inherit;text-decoration:none}
#comments .comment-content,#comments .comment-block p{font-size:14px;line-height:1.7;color:var(--ink);margin:0 0 8px;word-break:break-word}
#comments .comment-actions{font-size:12px}
#comments .comment-actions a{color:var(--grey);text-decoration:none;font-weight:600;margin-right:14px}
#comments .comment-actions a:hover{color:var(--red-t)}
#comments .comment-replies,#comments ol.loadable-comments{list-style:none;margin:10px 0 0 22px;padding:12px 0 0 16px;border-left:2px solid var(--line)}
#comments .comment-replybox-single,#comments .comment-replybox-thread{margin-top:10px}
#comments .continue{font-size:13px;color:var(--grey)}
.sz-comments .footer{margin-top:4px}
.sz-comments .comment-form{background:#fff;border:1px solid var(--line);border-radius:10px;padding:16px}
.sz-comments #comment-post-message{margin:0 0 10px;font-size:14px;font-weight:700;color:var(--ink)}
.sz-comments iframe#comment-editor{width:100%;border:0;border-radius:8px;min-height:220px;display:block}
.sz-comments .loadmore a,.sz-comments .loadMoreCommentsLink a{display:inline-block;margin-top:10px;font-size:13px;font-weight:700;color:var(--red-t);text-decoration:none}
.sz-inpost{display:none}
.sz-inpost.show{display:block;margin:0 0 20px;clear:both}
.sz-sharebox+.sz-inpost.show,.sz-inpost.show+.sz-sharebox{margin-top:20px}
.sz-next-pop{position:fixed;right:20px;bottom:20px;width:360px;max-width:calc(100vw - 40px);background:#fff;border-radius:10px;box-shadow:0 10px 30px rgba(0,0,0,.2);padding:14px 40px 14px 14px;display:flex;gap:12px;align-items:center;z-index:70;transform:translateY(140%);transition:transform .35s ease}
.sz-next-pop.show{transform:none}
.sz-next-pop .sz-thumb{width:80px;height:60px;flex:0 0 80px;border-radius:6px}
.sz-next-pop small{display:block;font-size:11px;font-weight:800;color:var(--red-t);text-transform:uppercase;margin-bottom:3px}
.sz-next-pop b{font-size:13px;line-height:1.4;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
.sz-next-x{position:absolute;top:6px;right:8px;border:0;background:none;font-size:16px;color:#666;padding:4px}
.sz-next{display:none}

/* ===== FOOTER ===== */
.sz-footer{background:linear-gradient(135deg,#c3092b 0,#850c47 50%,#46145e 100%);color:#fff;padding:40px 0 0;margin-top:30px}
.sz-foot-grid{display:flex;justify-content:space-between;gap:10px;padding-bottom:30px}
