.sz-foot-logo{display:inline-block;font-size:34px;font-weight:800;line-height:1;letter-spacing:-.8px;color:#fff!important;text-transform:lowercase}
.sz-foot-left .widget{margin:0}
.sz-foot-about{display:flex;flex-direction:column;gap:25px}
