.sz-network-title{font-size:13px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:rgba(255,255,255,.65);margin:0 0 20px}
.sz-network .widget{margin:0}
.sz-network .title,.sz-network h2,.sz-network h3{display:none}
.sz-network-list{display:flex!important;flex-wrap:wrap;justify-content:center;align-items:center;gap:14px 16px;list-style:none;margin:0;padding:0}
.sz-network-list li{list-style:none;display:flex}
.sz-network-list a{display:flex;align-items:center;opacity:.9;transition:opacity .15s,transform .15s}
.sz-network-list a:hover{opacity:1;transform:translateY(-2px)}
.sz-network-list img{display:block;height:34px;width:auto;max-width:160px;object-fit:contain;object-position:left center;border-radius:var(--radius)}
.sz-foot-bottom{display:grid;grid-template-columns:1fr 1fr;gap:20px}
