.sz-totop{position:fixed;right:16px;bottom:16px;width:42px;height:42px;border-radius:50%;background:var(--grad);color:#fff;display:flex;align-items:center;justify-content:center;opacity:0;visibility:hidden;transition:.25s;z-index:65}
