.sz-totop:hover{color:#fff}
.sz-is-post .sz-totop{bottom:16px;left:16px;right:auto}
.sz-toast{position:fixed;left:50%;bottom:24px;transform:translateX(-50%);background:#222;color:#fff;font-size:14px;padding:10px 18px;border-radius:30px;z-index:120}

