.sz-search{position:relative;display:block;flex:1;min-width:0;max-width:none;padding:0 10px;margin:0}.sz-search form{display:flex;align-items:center;width:550px;max-width:100%;height:34px;border:1px solid #d9d9d9;background:#fff;border-radius:25px;padding:0 7px 0 17px;margin:auto}.sz-search input{min-width:0;flex:1;width:0;border:0;border-radius:0;padding:6px 0;height:30px;font:400 13px var(--font);outline:0;background:none}.sz-search-hint,.sz-search-close{display:none}.sz-search-submit{display:grid;place-items:center;width:30px;height:30px;background:none;color:#555;border:0;border-radius:50%;padding:0}.sz-search-submit svg{width:18px;height:18px}
